    ...operations.state.settings,
    ...sanitizedUpdates,
    notifications: normalizeNotificationSettings({
      ...operations.state.settings.notifications,
      ...sanitizedUpdates.notifications
    }),
    ...(mergedTelemetry !== undefined ? { telemetry: mergedTelemetry } : {})
  }
